import{_ as n,a0 as o,w as p,s as l,ao as h,I as s,x as r,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux 下網絡協議分析器 Wireshark 使用基礎 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下網絡協議分析器 Wireshark 使用基礎 | LCTT (201704) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下網絡協議分析器 Wireshark 使用基礎 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下網絡協議分析器 Wireshark 使用基礎 | LCTT (201704) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201704/20170214 Basics of network protocol analyzer Wireshark On Linux","title":"Linux 下網絡協議分析器 Wireshark 使用基礎","tag":"201704","desc":""},"relativePath":"201704/20170214 Basics of network protocol analyzer Wireshark On Linux.md","filePath":"[post].md"}'),k={name:"201704/20170214 Basics of network protocol analyzer Wireshark On Linux.md"};function g(d,a,u,f,c,x){const i=o("Link");return p(),l("div",null,[a[13]||(a[13]=h('<h1 id="linux-下網絡協議分析器-wireshark-使用基礎" tabindex="-1">Linux 下網絡協議分析器 Wireshark 使用基礎 <a class="header-anchor" href="#linux-下網絡協議分析器-wireshark-使用基礎" aria-label="Permalink to “Linux 下網絡協議分析器 Wireshark 使用基礎”">​</a></h1><p>Wireshark 是 Kali 中預置的眾多有價值工具中的一種。與其它工具一樣，它可以被用於正面用途，同樣也可以被用於不良目的。當然，本文將會介紹如何追蹤你自己的網絡流量來發現潛在的非正常活動。</p><p>Wireshark 相當的強大，當你第一次見到它的時候可能會被它嚇到，但是它的目的始終就只有一個，那就是追蹤網絡流量，並且它所實現的所有選項都只為了加強它追蹤流量的能力。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>Kali 中預置了 Wireshark 。不過，<code>wireshark-gtk</code> 包提供了一個更好的界面使你在使用 Wireshark 的時候會有更友好的體驗。因此，在使用 Wireshark 前的第一步是安裝 <code>wireshark-gtk</code> 這個包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt install wireshark-gtk</span></span></code></pre></div><p>如果你的 Kali 是從 live 介質上運行的也不需要擔心，依然有效。</p><h3 id="基礎配置" tabindex="-1">基礎配置 <a class="header-anchor" href="#基礎配置" aria-label="Permalink to “基礎配置”">​</a></h3><p>在你使用 Wireshark 之前，將它設置成你使用起來最舒適的狀態可能是最好的。Wireshark 提供了許多不同的佈局方案和選項來配置程序的行為。儘管數量很多，但是使用起來是相當直接明確的。</p><p>從啓動 Wireshark-gtk 開始。需要確定啓動的是 GTK 版本的。在 Kali 中它們是被分別列出的。</p><p><img src="https://linuxconfig.org/images/wireshark-start.jpg?58a2b879" alt="Wireshark running on Kali"></p><h3 id="佈局" tabindex="-1">佈局 <a class="header-anchor" href="#佈局" aria-label="Permalink to “佈局”">​</a></h3><p>默認情況下，Wireshark 的信息展示分為三塊內容，每一塊都疊在另一塊上方。（LCTT 譯註：這裏的三部分指的是展示抓包信息的時候的那三塊內容，本段配圖沒有展示，配圖 4、5、6 的設置不是默認設置，與這裏的描述不符）最上方的一塊是所抓包的列表。中間的一塊是包的詳細信息。最下面那塊中包含的是包的原始字節信息。通常來説，上面的兩塊中的信息比最下面的那塊有用的多，但是對於資深用户來説這塊內容仍然是重要信息。</p><p>每一塊都是可以縮放的，可並不是每一個人都必須使用這樣疊起來的佈局方式。你可以在 Wireshark 的“選項（Preferences）”菜單中進行更改。點擊“編輯（Edit）”菜單，最下方就是的“選項”菜單。這個選項會打開一個有更多選項的新窗口。單擊側邊菜單中“用户界面（User Interface）”下的“佈局（Layout）”選項。</p><p><img src="https://linuxconfig.org/images/wireshark-layouts.jpg?58a2b879" alt="Wireshark&#39;s layout configuration"></p><p>你將會看到一些不同的佈局方案。上方的圖示可以讓你選擇不同的面板位置佈局方案，下面的單選框可以讓你選擇不同面板中的數據內容。</p><p>下面那個標記為“列（Columns）”的標籤可以讓你選擇展示所抓取包的哪些信息。選擇那些你需要的數據信息，或者全部展示。</p><h3 id="工具條" tabindex="-1">工具條 <a class="header-anchor" href="#工具條" aria-label="Permalink to “工具條”">​</a></h3><p>對於 Wireshark 的工具條能做的設置不是太多，但是如果你想設置的話，你依然在前文中提到的“佈局”菜單中的窗口管理工具下方找到一些有用的設置選項。那些能讓你配置工具條和工具條中條目的選項就在窗口選項下方。</p><p>你還可以在“視圖（View）”菜單下勾選來配置工具條的顯示內容。</p><h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><p>主要的用來控制 Wireshark 抓包的控制選項基本都集中在“捕捉（Capture）”菜單下的“選項（Options）”選項中。</p><p>在開啓的窗口中最上方的“捕捉（Capture）”部分可以讓你選擇 Wireshark 要監控的某個具體的網絡接口。這部分可能會由於你係統的配置不同而會有相當大的不同。要記得勾選正確的選擇框才能獲得正確的數據。虛擬機和伴隨它們一起的網絡接口也同樣會在這個列表裏顯示。同樣也會有多種不同的選項對應這多種不同的網絡接口。</p><p><img src="https://linuxconfig.org/images/wireshark-capture-config.jpg?58a2b879" alt="Wireshark&#39;s capture configuration"></p><p>在網絡接口列表的下方是兩個選項。其中一個選項是全選所有的接口。另一個選項用來選擇是否開啓混雜模式。這個選項可以使你的計算機監控到所選網絡上的所有的計算機。（LCTT 譯註：混雜模式可以在 HUB 中或監聽模式的交換機接口上捕獲那些由於 MAC 地址非本機而會被自動丟棄的數據包）如果你想監控你所在的整個網絡，這個選項是你所需要的。</p><p><strong>注意:</strong> 在一個不屬於你或者不擁有權限的網絡上使用混雜模式來監控是非法的！</p><p>在窗口下方的右側是“顯示選項（Display Options）”和“名稱解析（Name Resolution）”選項塊。對於“顯示選項（Display Options）”來説，三個選項全選可能就是一個很好的選擇了。當然你也可以取消選擇，但是最好還是保留選擇“實時更新抓包列表”。</p><p>在“名稱解析（Name Resolution）”中你也可以設置你的偏好。這裏的選項會產生附加的請求因此選得越多就會有越多的請求產生使你的抓取的包列表顯得雜亂。把 MAC 解析選項選上是個好主意，那樣就可以知道所使用的網絡硬件的品牌了。這可以幫助你來確定你是在與哪台設備上的哪個接口進行交互。</p><h3 id="抓包" tabindex="-1">抓包 <a class="header-anchor" href="#抓包" aria-label="Permalink to “抓包”">​</a></h3><p>抓包是 Wireshark 的核心功能。監控和記錄特定網絡上的流量就是它最初產生的目的。使用它最基本的方式來作這個抓包的工作是相當簡單方便的。當然，越多的配置和選項就越可以充分利用 Wireshark 的力量。這裏的介紹的關注點依然還是它最基本的記錄方式。</p><p>按下那個看起來像藍色鯊魚鰭的新建實時抓包按鈕就可以開始抓包了。（LCTT 譯註：在我的 Debian 上它是綠色的）</p><p><img src="https://linuxconfig.org/images/wireshark-packet-list.jpg?58a2b879" alt="Wireshark listing packet information"></p><p>在抓包的過程中，Wireshark 會收集所有它能收集到的包的數據並且記錄下來。如果沒有更改過相關設置的話，在抓包的過程中你會看見不斷的有新的包進入到“包列表”面板中。你可以實時的查看你認為有趣的包，或者就讓 Wireshark 運行着，同時你可以做一些其它的事情。</p><p>當你完成了，按下紅色的正方形“停止”按鈕就可以了。現在，你可以選擇是否要保存這些所抓取的數據了。要保存的話，你可以使用“文件”菜單下的“保存”或者是“另存為”選項。</p><h3 id="讀取數據" tabindex="-1">讀取數據 <a class="header-anchor" href="#讀取數據" aria-label="Permalink to “讀取數據”">​</a></h3><p>Wireshark 的目標是向你提供你所需要的所有數據。這樣做時，它會在它監控的網絡上收集大量的與網絡包相關的數據。它使用可摺疊的標籤來展示這些數據使得這些數據看起來沒有那麼嚇人。每一個標籤都對應於網絡包中一部分的請求數據。</p><p>這些標籤是按照從最底層到最高層一層層堆起來的。頂部標籤總是包含數據包中包含的字節數據。最下方的標籤可能會是多種多樣的。在下圖的例子中是一個 HTTP 請求，它會包含 HTTP 的信息。您遇到的大多數數據包將是 TCP 數據，它將展示在底層的標籤中。</p><p><img src="https://linuxconfig.org/images/wireshark-packet-info-http.jpg?58a2b879" alt="Wireshark listing HTTP packet info"></p><p>每一個標籤頁都包含了抓取包中對應部分的相關數據。一個 HTTP 包可能會包含與請求類型相關的信息，如所使用的網絡瀏覽器，服務器的 IP 地址，語言，編碼方式等的數據。一個 TCP 包會包含服務器與客户端使用的端口信息和 TCP 三次握手過程中的標誌位信息。</p><p><img src="https://linuxconfig.org/images/wireshark-packet-info-tcp.jpg?58a2b879" alt="Wireshark listing TCP packet info"></p><p>在上方的其它標籤中包含了一些大多數用户都感興趣的少量信息。其中一個標籤中包含了數據包是否是通過 IPv4 或者 IPv6 傳輸的，以及客户端和服務器端的 IP 地址。另一個標籤中包含了客户端和接入因特網的路由器或網關的設備的 MAC 地址信息。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>即使只使用這些基礎選項與配置，你依然可以發現 Wireshark 會是一個多麼強大的工具。監控你的網絡流量可以幫助你識別、終止網絡攻擊或者提升連接速度。它也可以幫你找到問題應用。下一篇 Wireshark 指南我們將會一起探索 Wireshark 的包過濾選項。</p><hr>',44)),s("p",null,[a[1]||(a[1]=r("via: ",-1)),e(i,{href:"https://linuxconfig.org/basic-of-network-protocol-analyzer-wireshark-on-linux"},{default:t(()=>[...a[0]||(a[0]=[r("https://linuxconfig.org/basic-of-network-protocol-analyzer-wireshark-on-linux",-1)])]),_:1})]),s("p",null,[a[5]||(a[5]=r("作者：",-1)),e(i,{href:"https://linuxconfig.org/basic-of-network-protocol-analyzer-wireshark-on-linux"},{default:t(()=>[...a[2]||(a[2]=[r("Nick Congleton",-1)])]),_:1}),a[6]||(a[6]=r(" 譯者：",-1)),e(i,{href:"https://github.com/wcnnbdk1"},{default:t(()=>[...a[3]||(a[3]=[r("wcnnbdk1",-1)])]),_:1}),a[7]||(a[7]=r(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...a[4]||(a[4]=[r("wxy",-1)])]),_:1})]),s("p",null,[a[10]||(a[10]=r("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[8]||(a[8]=[r("LCTT",-1)])]),_:1}),a[11]||(a[11]=r(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...a[9]||(a[9]=[r("Linux中國",-1)])]),_:1}),a[12]||(a[12]=r(" 榮譽推出",-1))])])}const W=n(k,[["render",g]]);export{b as __pageData,W as default};
